//
// D2 AU DERIVED COPY (make_d2_derived.py: d2_slot_verify3 + region 3 = slot 4, sound ROM, base3 / bytes3 -> sum3 / fl3,
// after the sprite region; done after it; a slot-4 size of 0 still terminates). Below: the d2_slot_verify3 header.
// D2 SP DERIVED COPY of rtl/d2_slot_verify.sv (generated by make_d2_derived.py): module renamed d2_slot_verify3, region 2 =
// slot 3 (sprite ROM, base2 / bytes2) added after the tile region with its own sum2 / fl2; everything else (word-serial fold,
// p5 protocol, per-region copy of the running sums, done after the LAST region) as the original. A slot-3 size of 0 (package
// without sprites.bin) still terminates: one burst is folded, the sums then differ from the expected ones.
//
// d2_slot_verify: D2's timing-closed form of experiments/P1-pocket-top/rtl/p1_slot_verify.sv (the frozen S2 file is unchanged).
// Same ports, same p5 request protocol, same two checksums per region over the 16-bit little-endian SDRAM words w[i]:
//     sum = sum(w[i]) mod 2^32,   fl = sum over i of sum(w[0..i]) mod 2^32,
// and the same final values. The only difference is the schedule: P1 folds a whole 4-word burst into both sums in ONE clk_ram
// cycle (8 chained 32-bit adds; -2.118 ns setup at 96.6 MHz in D2 fit run 42126911324, all 73 failing endpoints). Here the
// burst is latched on the ack edge and folded ONE WORD PER CLOCK over 4 cycles, each cycle one 2-input add (s) and one
// 3-input add (f + s + w = the new f), in parallel. Per region the working sums live in acc_s / acc_f and are copied to
// sum0/fl0 (region 0) or sum1/fl1 (region 1) when that region ends, so sum0..fl1 hold their final values from that edge on;
// P1 updated them burst by burst (only the values at done are used: d2_core_top's sums*_ok and the band).
// Cost: up to 4 extra clk_ram cycles per 8 bytes (P1's ack-fall wait overlaps them; <= ~33 ms for 6 MB at 96.6 MHz)
// before done, which releases the CPU reset.
// `cycles` (a diagnostic count of busy cycles) is therefore larger than P1's.
module d2_slot_verify4 (
    input              clk,
    input              rst,
    input              start,          // level; sampled once
    input       [24:0] base0, input [24:0] bytes0,
    input       [24:0] base1, input [24:0] bytes1,
    input       [24:0] base2, input [24:0] bytes2,   // SP: slot 3 (sprite ROM)
    input       [24:0] base3, input [24:0] bytes3,   // AU: slot 4 (sound ROM)
    output reg         p5_req = 1'b0,
    output reg  [24:3] p5_addr = 0,
    input       [63:0] p5_dout,
    input              p5_ack,
    output reg         done = 1'b0,
    output reg  [31:0] sum0 = 0, fl0 = 0, sum1 = 0, fl1 = 0, sum2 = 0, fl2 = 0, sum3 = 0, fl3 = 0,
    output reg  [31:0] cycles = 0
);
localparam [2:0] S_IDLE = 3'd0, S_ISSUE = 3'd1, S_WAIT = 3'd2, S_FALL = 3'd3, S_ACC = 3'd4;
reg [2:0]  st = S_IDLE;
reg [1:0]  region = 0;               // SP: 0 program, 1 tiles, 2 sprites; AU: 3 sound
reg [24:0] off = 0;
reg        ack_d = 1'b0;
reg [63:0] buf_q = 0;              // the burst, latched on the ack edge
reg [1:0]  k = 0;                  // word index within the burst
reg [31:0] acc_s = 0, acc_f = 0;   // the current region's running sums
wire [15:0] w      = buf_q[16*k +: 16];
wire [31:0] s_next = acc_s + 32'(w);
wire [31:0] f_next = acc_f + acc_s + 32'(w);          // = acc_f + s_next
wire [24:0] bytes_r = (region == 2'd3) ? bytes3 : region[1] ? bytes2 : region[0] ? bytes1 : bytes0;
wire        last   = (off + 25'd8 >= bytes_r);
always @(posedge clk) begin
    ack_d <= p5_ack;
    p5_req <= 1'b0;
    if (rst) begin
        st <= S_IDLE; done <= 1'b0; region <= 0; off <= 0; k <= 0; acc_s <= 0; acc_f <= 0;
        sum0 <= 0; fl0 <= 0; sum1 <= 0; fl1 <= 0; sum2 <= 0; fl2 <= 0; sum3 <= 0; fl3 <= 0; cycles <= 0;
    end else begin
        if (st != S_IDLE && !done) cycles <= cycles + 1;
        case (st)
        S_IDLE: if (start && !done) begin st <= S_ISSUE; region <= 0; off <= 0; acc_s <= 0; acc_f <= 0; end
        S_ISSUE: begin   // one-cycle request pulse = one rising edge (as P1)
            p5_addr <= 22'((((region == 2'd3) ? base3 : region[1] ? base2 : region[0] ? base1 : base0) + off) >> 3);
            p5_req  <= 1'b1;
            st <= S_WAIT;
        end
        S_WAIT: if (p5_ack && !ack_d) begin buf_q <= p5_dout; k <= 2'd0; st <= S_ACC; end
        S_ACC: begin
            acc_s <= s_next; acc_f <= f_next; k <= k + 2'd1;
            if (k == 2'd3) begin
                if (last) begin
                    if (region == 2'd3) begin sum3 <= s_next; fl3 <= f_next; done <= 1'b1; st <= S_IDLE; end
                    else if (region[1]) begin sum2 <= s_next; fl2 <= f_next; region <= 2'd3; off <= 0;
                               acc_s <= 0; acc_f <= 0; st <= S_FALL; end
                    else if (region[0]) begin sum1 <= s_next; fl1 <= f_next; region <= 2'd2; off <= 0;
                               acc_s <= 0; acc_f <= 0; st <= S_FALL; end
                    else begin sum0 <= s_next; fl0 <= f_next; region <= 2'd1; off <= 0;
                               acc_s <= 0; acc_f <= 0; st <= S_FALL; end
                end else begin off <= off + 25'd8; st <= S_FALL; end
            end
        end
        S_FALL: if (!p5_ack) st <= S_ISSUE;   // let the stretched ack fall before the next request edge (as P1)
        default: st <= S_IDLE;
        endcase
    end
end
endmodule
